import sys

mod = 998244353

def pw(a, b):
    res = 1
    while b > 0:
        if b & 1:
            res = res * a % mod
        a = a * a % mod
        b >>= 1
    return res

def inv(a):
    return pw(a, mod - 2)

# Precompute factorials up to 500000
max_n = 500000
f = [1] * (max_n + 1)
for i in range(2, max_n + 1):
    f[i] = f[i - 1] * i % mod

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    k = int(data[1])
    ans = 0
    for i in range(1, n - k + 2):
        cnt = n // i
        if cnt < k:
            continue
        # C(cnt-1, k-1)
        comb = f[cnt - 1] * inv(f[k - 1]) % mod * inv(f[cnt - k]) % mod
        ans = (ans + comb) % mod
    print(ans)

if __name__ == "__main__":
    solve()

